package com.example.rokidgeminisecretary;
import org.json.*;
/** On-demand local search. Never uploads, rewrites, or claims an exhaustive cloud index. */
final class UnifiedRecords {
 static JSONObject item(String type,String id,long at,String title,String body)throws Exception{return new JSONObject().put("type",type).put("id",id).put("at",at).put("title",title.length()>160?title.substring(0,160):title).put("body",body);}
 static JSONObject catalog(MainActivity owner)throws Exception{JSONArray all=new JSONArray(),issues=new JSONArray();JSONObject counts=new JSONObject();try{ImportedAnswers.store(owner);}catch(Exception unreadable){issues.put("取り込み済み回答");}try{JSONArray rows=owner.localRecordConversations();counts.put("conversation",rows.length());for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);String body=row.optString("message");JSONObject record=item("conversation",RecorderPhotoStore.hash((row.optLong("time")+":"+row.optString("kind")+":"+body).getBytes("UTF-8")),row.optLong("time"),row.optString("kind","会話")+(row.optBoolean("legacy")?"（更新前の保存履歴・抜粋）":""),body);if(AnswerCorrections.eligible(row))record.put("answer",AnswerCorrections.source(row));all.put(record);}}catch(Exception e){issues.put("会話記録");}try{JSONArray rows=SecretaryInbox.list(owner).getJSONArray("items");counts.put("inbox",rows.length());for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);all.put(item("inbox",row.getString("id"),row.optLong("createdAt"),row.optString("title"),row.optString("request")+"\n"+row.optString("conditions")+"\n"+row.optString("date_text")).put("pending",row.optString("state").equals("pending")));}}catch(Exception e){issues.put("受信箱");}try{JSONArray rows=MeetingAudioStore.list(owner);counts.put("meeting",Math.min(100,rows.length()));if(rows.length()>100)issues.put("会議は直近100件を対象");for(int i=0;i<Math.min(100,rows.length());i++){JSONObject row=rows.getJSONObject(i);all.put(item("meeting",row.getString("id"),row.optLong("startedAt"),row.optString("title","会議"),row.optString("summary")));}}catch(Exception e){issues.put("会議要約");}try{JSONArray rows=ReadingHistory.list(owner);counts.put("reading",rows.length());for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);all.put(item("reading",row.getString("id"),row.getLong("at"),row.optString("question","画像の読み取り"),row.getString("answer")+"\n訂正履歴："+row.getJSONArray("corrections")));}}catch(Exception e){issues.put("画像の読み取り履歴");}try{JSONArray notes=PersonalNotes.list(owner);counts.put("notes",notes.length());for(int i=0;i<notes.length();i++){JSONObject note=notes.getJSONObject(i);all.put(item(note.getString("kind"),note.getString("id"),note.getLong("at"),note.getString("kind").equals("memo")?"メモ":"会話の続き",note.getString("text")));}}catch(Exception e){issues.put("メモ・会話の続き");}return new JSONObject().put("items",all).put("issues",issues).put("counts",counts);}
 static JSONObject resolve(JSONObject catalog,String type,String id)throws Exception{JSONObject found=null;JSONArray rows=catalog.getJSONArray("items");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(type.equals(row.optString("type"))&&id.equals(row.optString("id"))){if(found!=null)throw new java.io.IOException("同じIDの記録が複数あります。元の記録を確認してください");found=row;}}if(found==null)throw new java.io.IOException("元の記録は削除・対象外・未取得です。保存したコピーは保持しています");return found;}
 static JSONObject search(MainActivity owner,String query)throws Exception{return search(owner,query,new JSONObject());}
 static JSONObject search(MainActivity owner,String query,JSONObject filter)throws Exception{
  String type=filter.optString("type");if(!type.matches("|conversation|meeting|reading|inbox|memo|continuation"))throw new IllegalArgumentException("検索の種類が不正です");long from=filter.optLong("from",0),until=filter.optLong("until",Long.MAX_VALUE);if(from<0||until<from)throw new IllegalArgumentException("日付の範囲を確認してください");boolean pending=filter.optBoolean("pending");if(query==null||RecordSearchPolicy.normalized(query).isEmpty()||query.length()>160)throw new IllegalArgumentException("検索語を1〜160文字で入力してください");JSONObject catalog=catalog(owner);JSONArray all=catalog.getJSONArray("items"),issues=catalog.getJSONArray("issues");JSONObject counts=catalog.getJSONObject("counts");java.util.ArrayList<JSONObject> found=new java.util.ArrayList<>();java.util.HashSet<String> seen=new java.util.HashSet<>();for(int i=0;i<all.length();i++){JSONObject row=all.getJSONObject(i);String id=row.getString("type")+":"+row.getString("id");if((type.isEmpty()||type.equals(row.optString("type")))&&row.optLong("at")>=from&&row.optLong("at")<=until&&(!pending||row.optBoolean("pending"))&&seen.add(id)&&RecordSearchPolicy.matches(row.optString("title")+" "+row.getString("body"),query))found.add(row);}found.sort((a,b)->Long.compare(b.optLong("at"),a.optLong("at")));JSONArray result=new JSONArray();for(int i=0;i<Math.min(50,found.size());i++)result.put(found.get(i));return new JSONObject().put("items",result).put("matched",found.size()).put("counts",counts).put("issues",issues).put("scope","端末内のメモ・会話の続き、会話・長期記憶、直近100件の会議要約、受信箱、今回以降に保持した画像読み取り100件・90日。検索結果は最大50件。クラウドや全写真のOCR検索ではありません。");}
 private UnifiedRecords(){}
}
